CREATE TABLE organization_work(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL REFERENCES organizations(id),creator_id BIGINT NOT NULL REFERENCES app_users(id),assignee_id BIGINT REFERENCES app_users(id),kind VARCHAR(20) NOT NULL CHECK(kind IN ('ROLE','SUGGESTION','TASK')),title VARCHAR(200) NOT NULL,content TEXT NOT NULL,requested_role VARCHAR(20),status VARCHAR(20) NOT NULL CHECK(status IN ('PENDING','ACCEPTED','REJECTED','CANCELLED','DONE','ANSWERED')),response TEXT,due_at TIMESTAMPTZ,updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_organization_work ON organization_work(organization_id,kind);
